window.COMMIT_ZERO_SOURCES = {"play.js":{"text":"const kind = new URLSearchParams(location.search).get(\"game\") || \"orbit\",\n  c = document.getElementById(\"canvas\"),\n  ctx = c.getContext(\"2d\"),\n  button = document.getElementById(\"action\"),\n  message = document.getElementById(\"message\"),\n  scoreLabel = document.getElementById(\"score\");\nlet width = 0,\n  height = 0,\n  raf = 0,\n  last = 0,\n  playing = false,\n  score = 0,\n  angle = -Math.PI / 2,\n  attempts = 0,\n  blocks = [],\n  moving = { x: 0, w: 100 },\n  direction = 1,\n  ended = false,\n  phase = \"idle\",\n  signalTimer = null,\n  readyAt = 0;\nfunction resize() {\n  const dpr = devicePixelRatio || 1;\n  width = c.clientWidth;\n  height = c.clientHeight;\n  c.width = width * dpr;\n  c.height = height * dpr;\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  if (!playing) draw();\n}\nfunction text(t, x, y, size = 20, color = \"#51627a\") {\n  ctx.fillStyle = color;\n  ctx.font = `600 ${size}px 'Segoe UI',sans-serif`;\n  ctx.textAlign = \"center\";\n  ctx.fillText(t, x, y);\n}\nfunction draw() {\n  ctx.clearRect(0, 0, width, height);\n  if (kind === \"orbit\") {\n    const x = width / 2,\n      y = height / 2,\n      r = Math.min(85, height * 0.31);\n    ctx.lineWidth = 2;\n    ctx.strokeStyle = \"#cfdae7\";\n    ctx.beginPath();\n    ctx.arc(x, y, r, 0, Math.PI * 2);\n    ctx.stroke();\n    ctx.lineWidth = 12;\n    ctx.strokeStyle = \"#5e8ab7\";\n    ctx.beginPath();\n    ctx.arc(x, y, r, -0.95, -0.45);\n    ctx.stroke();\n    ctx.fillStyle = \"#252b34\";\n    ctx.beginPath();\n    ctx.arc(\n      x + Math.cos(angle) * r,\n      y + Math.sin(angle) * r,\n      7,\n      0,\n      Math.PI * 2,\n    );\n    ctx.fill();\n    text(String(score), x, y + 6, 34);\n    text(\"попаданий\", x, y + 29, 11, \"#697381\");\n  } else if (kind === \"tower\") {\n    ctx.fillStyle = \"#dddfe3\";\n    ctx.fillRect(20, height - 21, width - 40, 1);\n    const visible = blocks.slice(-8);\n    visible.forEach((b, i) => {\n      ctx.fillStyle = i % 2 ? \"#c89577\" : \"#b47b5d\";\n      ctx.fillRect(b.x * width, height - 40 - i * 24, b.w * width, 20);\n    });\n    if (!ended) {\n      ctx.fillStyle = \"#e1aa88\";\n      ctx.fillRect(\n        moving.x * width,\n        height - 40 - visible.length * 24,\n        moving.w * width,\n        20,\n      );\n    }\n    if (ended) text(\"Башня: \" + score + \" этажей\", width / 2, 38, 22);\n  } else {\n    const x = width / 2,\n      y = height / 2;\n    ctx.fillStyle =\n      phase === \"ready\"\n        ? \"#d4eee0\"\n        : phase === \"waiting\"\n          ? \"#f7e8de\"\n          : \"#e6ecf6\";\n    ctx.fillRect(0, 0, width, height);\n    ctx.fillStyle =\n      phase === \"ready\"\n        ? \"#388460\"\n        : phase === \"waiting\"\n          ? \"#b88a66\"\n          : \"#8f9bb1\";\n    ctx.beginPath();\n    ctx.arc(x, y - 18, 27, 0, Math.PI * 2);\n    ctx.fill();\n    text(\n      phase === \"ready\"\n        ? \"Нажимай!\"\n        : phase === \"waiting\"\n          ? \"Жди зелёного\"\n          : phase === \"result\"\n            ? message.textContent\n            : \"Проверь реакцию\",\n      x,\n      y + 47,\n      phase === \"result\" ? 18 : 22,\n    );\n  }\n}\nfunction loop(now) {\n  const dt = Math.min((now - last) / 1000, 0.04);\n  last = now;\n  if (kind === \"orbit\") angle += dt * (1.7 + score * 0.2);\n  if (kind === \"tower\") {\n    moving.x += direction * dt * (0.34 + score * 0.025);\n    if (moving.x \u003c 0.02) {\n      moving.x = 0.02;\n      direction = 1;\n    }\n    if (moving.x + moving.w > 0.98) {\n      moving.x = 0.98 - moving.w;\n      direction = -1;\n    }\n  }\n  draw();\n  if (playing) raf = requestAnimationFrame(loop);\n}\nfunction startLoop() {\n  cancelAnimationFrame(raf);\n  playing = true;\n  last = performance.now();\n  raf = requestAnimationFrame(loop);\n}\nfunction stopLoop() {\n  playing = false;\n  cancelAnimationFrame(raf);\n}\nfunction startTower() {\n  score = 0;\n  ended = false;\n  blocks = [{ x: 0.32, w: 0.36 }];\n  moving = { x: 0.02, w: 0.36 };\n  direction = 1;\n  scoreLabel.textContent = \"Этажей: 0\";\n  button.textContent = \"Поставить блок\";\n  message.textContent = \"Нажми, когда блок будет над башней.\";\n  startLoop();\n}\nfunction react() {\n  if (phase === \"idle\" || phase === \"result\") {\n    phase = \"waiting\";\n    button.textContent = \"Жду сигнал\";\n    message.textContent = \"Дождись зелёного круга. Раньше нажимать нельзя.\";\n    draw();\n    signalTimer = setTimeout(\n      () => {\n        phase = \"ready\";\n        readyAt = performance.now();\n        button.textContent = \"Нажать!\";\n        message.textContent = \"Зелёный — нажимай!\";\n        draw();\n      },\n      1500 + Math.random() * 2200,\n    );\n  } else if (phase === \"waiting\") {\n    clearTimeout(signalTimer);\n    phase = \"result\";\n    message.textContent = \"Слишком рано! Попробуй ещё раз.\";\n    button.textContent = \"Попробовать снова\";\n    draw();\n  } else if (phase === \"ready\") {\n    const ms = Math.round(performance.now() - readyAt);\n    phase = \"result\";\n    message.textContent = ms + \" мс — твоё время реакции\";\n    scoreLabel.textContent = \"Последний результат: \" + ms + \" мс\";\n    button.textContent = \"Попробовать снова\";\n    draw();\n  }\n}\nbutton.onclick = () => {\n  if (kind === \"reaction\") {\n    react();\n    return;\n  }\n  if (kind === \"tower\") {\n    if (!playing) {\n      startTower();\n      return;\n    }\n    const prev = blocks[blocks.length - 1],\n      left = Math.max(prev.x, moving.x),\n      right = Math.min(prev.x + prev.w, moving.x + moving.w);\n    if (right - left \u003c= 0.008) {\n      stopLoop();\n      ended = true;\n      button.textContent = \"Начать заново\";\n      message.textContent = \"Блок упал. Твоя башня: \" + score + \" этажей.\";\n      draw();\n      return;\n    }\n    blocks.push({ x: left, w: right - left });\n    score++;\n    scoreLabel.textContent = \"Этажей: \" + score;\n    moving = { x: score % 2 ? 0.02 : 0.98 - (right - left), w: right - left };\n    direction = score % 2 ? 1 : -1;\n    message.textContent = \"Есть! Поставь следующий блок.\";\n    draw();\n    return;\n  }\n  if (!playing) {\n    startLoop();\n    button.textContent = \"Остановить\";\n    message.textContent = \"Попади спутником в синий сектор.\";\n  } else {\n    stopLoop();\n    attempts++;\n    const diff = Math.atan2(Math.sin(angle + 0.7), Math.cos(angle + 0.7));\n    const hit = Math.abs(diff) \u003c= 0.25;\n    if (hit) score++;\n    scoreLabel.textContent = \"Попаданий: \" + score + \" / \" + attempts;\n    message.textContent = hit\n      ? \"Попадание! Скорость увеличилась.\"\n      : \"Мимо. Попробуй ещё раз.\";\n    button.textContent = \"Следующая попытка\";\n    draw();\n  }\n};\ndocument.getElementById(\"label\").textContent =\n  { orbit: \"Орбита\", tower: \"Башня\", reaction: \"Реакция\" }[kind] || \"Орбита\";\nif (kind === \"tower\") {\n  blocks = [{ x: 0.32, w: 0.36 }];\n  moving = { x: 0.05, w: 0.36 };\n}\nwindow.addEventListener(\"resize\", resize);\ndocument.addEventListener(\"keydown\", (e) => {\n  if (e.code === \"Space\" && e.target !== button) {\n    e.preventDefault();\n    if (!e.repeat) button.click();\n  }\n  if (e.code === \"Escape\")\n    window.parent.postMessage({ type: \"commit-zero-close\" }, \"*\");\n});\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (document.hidden) {\n    clearTimeout(signalTimer);\n    if (kind === \"reaction\" && (phase === \"waiting\" || phase === \"ready\")) {\n      phase = \"idle\";\n      button.textContent = \"Начать\";\n      message.textContent = \"Игра приостановлена.\";\n      draw();\n    }\n    if (playing) {\n      stopLoop();\n      button.textContent =\n        kind === \"tower\" ? \"Начать заново\" : \"Следующая попытка\";\n      message.textContent = \"Игра приостановлена.\";\n    }\n  }\n});\nresize();\n","size":"7.8"},"play.html":{"text":"\u003c!doctype html>\n\u003chtml lang=\"ru\">\n  \u003chead>\n    \u003cmeta charset=\"utf-8\" />\n    \u003cmeta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n    \u003ctitle>Мини-игра — Commit Zero\u003c/title>\n    \u003clink rel=\"icon\" href=\"data:,\" />\n    \u003cstyle>\n      * {\n        box-sizing: border-box;\n      }\n      body {\n        margin: 0;\n        padding: 18px 22px 20px;\n        color: #252b34;\n        background: #fff;\n        font:\n          14px/1.5 \"Segoe UI\",\n          Arial,\n          sans-serif;\n        text-align: center;\n      }\n      .top {\n        display: flex;\n        justify-content: space-between;\n        font-size: 12px;\n        color: #697381;\n        margin: 0 0 10px;\n      }\n      #score {\n        font-variant-numeric: tabular-nums;\n        color: #252b34;\n      }\n      canvas {\n        width: 100%;\n        height: 275px;\n        display: block;\n        border-radius: 8px;\n        background: #f2f5f9;\n      }\n      button {\n        display: block;\n        width: 100%;\n        margin-top: 18px;\n        min-height: 48px;\n        background: #252b34;\n        color: white;\n        border: 0;\n        border-radius: 7px;\n        font:\n          600 15px \"Segoe UI\",\n          Arial,\n          sans-serif;\n        cursor: pointer;\n      }\n      button:focus-visible {\n        outline: 3px solid #245fe5;\n        outline-offset: 4px;\n      }\n      button:disabled {\n        background: #e9edf2;\n        color: #6a7688;\n        cursor: default;\n      }\n      p {\n        margin: 12px 0 0;\n        color: #697381;\n        font-size: 13px;\n        min-height: 40px;\n      }\n      @media (max-width: 420px) {\n        body {\n          padding: 12px 15px;\n        }\n        canvas {\n          height: 240px;\n        }\n        button {\n          margin-top: 14px;\n        }\n        p {\n          font-size: 12px;\n        }\n      }\n    \u003c/style>\n    \u003cscript src=\"play.js\" defer>\u003c/script>\n  \u003c/head>\n  \u003cbody>\n    \u003cdiv class=\"top\">\n      \u003cspan id=\"label\">Одна кнопка\u003c/span>\u003cspan id=\"score\">Счёт: 0\u003c/span>\n    \u003c/div>\n    \u003ccanvas id=\"canvas\" role=\"img\" aria-label=\"Игровое поле\">\u003c/canvas\n    >\u003cbutton id=\"action\">Начать\u003c/button>\n    \u003cp id=\"message\" role=\"status\">Нажми кнопку, чтобы начать.\u003c/p>\n  \u003c/body>\n\u003c/html>\n","size":"2.2"},"README.md":{"text":"# Commit Zero / season-01\n\nОдна задача: создать игру с одной кнопкой.\nТри участника в демонстрации: ChatGPT, Claude и Gemini.\n\n## Игры\n\n- Орбита: останови спутник в синем секторе.\n- Башня: ставь блоки друг на друга.\n- Реакция: нажми, когда появится зелёный сигнал.\n\nВсе три игры работают в браузере. Крестик или Escape закрывают игру.\nПросмотр файлов на главной показывает настоящие исходники play.js и play.html.\nУчастие ИИ, анимация написания кода и оценки — симуляция.\n\n## Запуск\n\nИз X:\\ai-github:\n\n```powershell\nnode prototype/build.mjs\npython -m http.server 4173 --bind 127.0.0.1 --directory prototype\n```\n\nОткрыть http://127.0.0.1:4173/. Сервер должен оставаться запущенным.\n\n## Устройство прототипа\n\n- github.html — основной шаблон страницы.\n- github.css — оформление в духе GitHub поверх minimal.css.\n- github.js — просмотр, подсветка, копирование и скачивание исходников.\n- minimal.js — игровые окна и симуляция процесса.\n- play.html и play.js — поле, управление и логика трёх игр.\n- build-v3.mjs — сборка главной и снимка исходников source-data.js.\n\nПосле правок файлов запускать сборку, чтобы обновить просмотр кода.\nПредыдущее оформление сохранено в ../prototype-backup-v2/.\n\nЛоготипы: https://github.com/lobehub/lobe-icons.\nЛицензия: assets/LICENSE-lobe-icons.txt.\nПроект не связан с GitHub, OpenAI, Anthropic или Google.\n","size":"2.0"}};
